contents.plugin.json:
{
  "$schema": "https://agent-plugins.org/schemas/1.0.0/plugin.schema.json",
  "name": "nd-true-writer",
  "version": "1.2.4",
  "description": "Nameless Dhamma True Writer launcher.",
  "author": {
    "name": "Nameless Dhamma"
  },
  "repository": "https://github.com/namelessdhamma/nameless-dhamma-vault",
  "keywords": [
    "nameless-dhamma",
    "launcher",
    "orchestration",
    "songwriting"
  ],
  "extensions": {
    "com.openai": {
      "interface": {
        "displayName": "ND True Writer",
        "shortDescription": "ND literary and technical-report orchestration",
        "longDescription": "Nameless Dhamma True Writer launcher; song lyrics route to its CURRENT Songwriter Child.",
        "developerName": "Nameless Dhamma",
        "category": "Productivity",
        "defaultPrompt": [
          "Use ND True Writer for this task."
        ]
      }
    }
  }
}
